/// Everything the prompt needs.
pub struct PromptInputs<'a> {
    pub raw: bool,
    pub purpose: &'a str,
    pub prompt: &'a str,
    /// The repo-relative brief path (empty when none).
    pub brief_ref: &'a str,
    pub range: Option<&'a Range>,
    pub open_findings: &'a [OpenFinding],
    /// `output-schema` | `native` | `prompt-only`.
    pub schema_transport: &'a str,
    /// The reply schema text, inlined only when the transport is prompt-only.
    pub schema_text: &'a str,
    pub max_words: u32,
    pub consult_id: &'a str,
    /// The engine's `Tools:` line (D11), added after the ask/brief/range for a non-codex
    /// engine; empty for codex.
    pub tools_line: &'a str,
    /// A panel member's role paragraph (`role_prompt_line`), added after the ask and before the
    /// brief (`codex-consult.ps1:3555`); empty when the run has no role.
    pub role_line: &'a str,
    /// (wave 26b, D16) the reviewer's context-window line, added right after the ask when its
    /// roster entry names a `context_tokens`; empty otherwise.
    pub context_line: &'a str,
    /// (wave 26b, D16) the "your previous reply is <path>" line, added when a fork/resume was
    /// downgraded to a new thread because the previous one is too large; empty otherwise.
    pub prev_reply_line: &'a str,
}

const NL: &str = "\r\n";

/// Assemble the full prompt text.
pub fn assemble(inp: &PromptInputs) -> String {
    let mut parts: Vec<String> = Vec::new();
    if !inp.raw {
        parts.push(FINAL_OUTPUT_CONTRACT.to_string());
    }
    if !inp.prompt.is_empty() {
        parts.push(inp.prompt.trim().to_string());
    }
    // (wave 26b, D16) a reviewer with a known context window is told so, right after the ask.
    if !inp.context_line.is_empty() {
        parts.push(inp.context_line.to_string());
    }
    // (wave 26b, D16) a downgraded fork/resume names the previous reply to re-read.
    if !inp.prev_reply_line.is_empty() {
        parts.push(inp.prev_reply_line.to_string());
    }
    // A panel member's role goes after the ask, before the brief (never inside the contract).
    if !inp.role_line.is_empty() {
        parts.push(inp.role_line.to_string());
    }
    if !inp.brief_ref.is_empty() {
        parts.push(format!(
            "Read the brief at `{}` (path relative to the repository root, which is your working directory) and answer every numbered question in it.",
            inp.brief_ref
        ));
    }
    if let Some(r) = inp.range {
        parts.push(format!(
            "Review range: `{}` - {} ({} insertions, {} deletions; git diff --shortstat). Plan your reading for its size.",
            r.spec, r.text, r.insertions, r.deletions
        ));
    }
    // The engine's own tools line (D11), after the ask/brief/range; empty for codex.
    if !inp.tools_line.is_empty() {
        parts.push(inp.tools_line.to_string());
    }
    if inp.raw {
        if inp.purpose == "chore" {
            parts.push(format!("Review purpose: chore. {}", presets::text("chore")));
        }
        parts.push(format!(
            "Constraints: write NO files and make no edits - this is a read-only consultation; answer in English; keep the answer under {} words.",
            inp.max_words
        ));
    } else {
        if !inp.purpose.is_empty() {
            parts.push(format!(
                "Review purpose: {}. {}",
                inp.purpose,
                presets::text(inp.purpose)
            ));
        }
        if !inp.open_findings.is_empty() {
            parts.push(render_open_findings(inp.open_findings));
        }
        parts.push(schema_block(inp));
        if inp.schema_transport == "prompt-only" {
            parts.push(format!("JSON Schema of the reply:{NL}{}", inp.schema_text));
        }
        parts.push(format!(
            "Constraints: write NO files and make no edits - this is a read-only consultation; answer in English; keep reply_markdown under {} words.",
            inp.max_words
        ));
    pub created: Option<chrono::DateTime<chrono::Utc>>,
    pub command_line: String,
}

/// A process the scan attributes to an interrupted run.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FoundProc {
    pub pid: u32,
    pub name: String,
    pub rule: String,
}

/// The outcome of one scan pass (`Find-CodexProcesses`'s return object).
#[derive(Debug, Clone)]
pub struct ScanOutcome {
    pub found: Vec<FoundProc>,
    pub check: String,
    pub failed: bool,
}

/// `Get-CodexRule`: why a process looks like codex (the rule label), or `""` when it does not.
/// `name` is the image name (with or without `.exe`), `cmd` its command line, `launcher` the
/// recorded launcher path (empty when none).
pub fn codex_rule(name: &str, cmd: &str, launcher: &str) -> String {
    let name_l = name.to_ascii_lowercase();
    if name_l == "codex" || name_l == "codex.exe" {
        return "name codex".to_string();
    }
    if !launcher.is_empty() && !name.is_empty() {
        let path = std::path::Path::new(launcher);
        let ext = path
            .extension()
            .map(|e| e.to_string_lossy().to_ascii_lowercase())
            .unwrap_or_default();
        let base = path
            .file_stem()
            .map(|b| b.to_string_lossy().to_string())
            .unwrap_or_default();
        let name_base = if name_l.ends_with(".exe") {
            &name[..name.len() - 4]
        } else {
            name
        };
        if !base.is_empty()
            && (ext.is_empty() || ext == "exe")
            && name_base.eq_ignore_ascii_case(&base)
        {
            return format!("name {base} (the recorded launcher)");
        }
    }
    if !launcher.is_empty()
        && !cmd.is_empty()
        && cmd
            .to_ascii_lowercase()
            .contains(&launcher.to_ascii_lowercase())
    {
        return "launcher in command line".to_string();
    }
    let cmd_l = cmd.to_ascii_lowercase();
    if cmd_l.contains("@openai/codex") || cmd_l.contains("@openai\\codex") {
        return "@openai/codex in command line".to_string();
    }
    String::new()
}

/// `Find-CodexProcesses` over a given process list (pure). `since_text` is the pre-formatted
/// "started at or after" stamp for the message; `since` is the same instant for the comparison.
/// With a bridge pid on Windows, a process counts when its parent is that pid and it started at or
/// after `since` (and, if the pid was reused by a live process, before that reuse). Otherwise the
/// machine-wide "looks like codex" rule applies (labelled "task not verifiable"). This process and
/// its ancestors are never counted.
#[allow(clippy::too_many_arguments)]
pub fn find_codex_processes(
    procs: &[ScanProc],
    since: chrono::DateTime<chrono::Utc>,
    since_text: &str,
    launcher: &str,
    bridge_pid: u32,
    self_pid: u32,
    on_windows: bool,
) -> ScanOutcome {
    let by_parent = on_windows && bridge_pid > 0;
    let rules = if by_parent {
        format!("children of the interrupted bridge pid {bridge_pid}")
    } else {
        "name codex*, or a command line containing the recorded launcher or @openai/codex"
            .to_string()
    };
    let scanner = if on_windows {
        "Win32_Process scan"
            "{TOOL}: {orphan_count} finding(s) and {orphan_check_count} reviewer check(s) belong to no ledger entry (ORPHAN; see -List -All)."
        );
    }
    write_pending_line(&ctx.task_dir);
    Ok(0)
}

