                ts.iter()
                    .filter_map(|t| t.as_str().map(str::to_string))
                    .collect()
            })
            .unwrap_or_default();
        let _ = crate::telemetry::record_rating(entry, &ctx.useful, age_days, &raw_topics);
    }

