    pub engine: String,
    /// Provider label (safe) or `unknown`.
    pub provider: String,
    /// Model label (safe) or `unknown`.
    pub model: String,
    /// Purpose label (safe) or `unknown`.
    pub purpose: String,
    /// `usable` or `failed:<class>`.
    pub outcome: String,
    pub wall_seconds: f64,
    pub tokens_in: i64,
    pub tokens_out: i64,
    pub findings: i64,
    pub structured: bool,
    pub format_retry: bool,
    pub panel_size: u32,
